export const BODY: string = "\n<p>ای میل، چیٹ میسج یا API جواب میں متن کی لمبی دیوار آتی ہے، اور اس کے اندر کہیں ایک تصویر چھپی ہوتی ہے۔ متن Base64 اسٹرنگ ہوتا ہے، اور تصویر اسی کے اندر ہوتی ہے۔</p>\n<p>ڈی کوڈنگ اس اسٹرنگ کو واپس اصل تصویری فائل میں بدل دیتی ہے۔ یہ انکوڈنگ کا الٹ ہے، اور اتنا ہی لاس لیس ہے: جو بائٹ نکلتے ہیں وہ وہی بائٹ ہوتے ہیں جو انکوڈ کیے گئے تھے۔</p>\n<p>اس گائیڈ میں بتایا گیا ہے کہ CompressMyPic کا Base64 to image ڈی کوڈر کیسے کام کرتا ہے، وہ کیا قبول کرتا ہے، وہ کیا دکھاتا ہے، اور کسی بھی Base64 اسٹرنگ سے قابلِ استعمال تصویری فائل کیسے حاصل کریں۔</p>\n<h2 id=\"what-is-base64-to-image\">Base64 to Image ڈی کوڈر کیا ہے؟</h2>\n<p>Base64 to image ڈی کوڈر متن کی اسٹرنگ لیتا ہے اور اسے واپس ایسی تصویری فائل میں بدل دیتا ہے جسے آپ دیکھ، ڈاؤن لوڈ اور استعمال کر سکتے ہیں۔ یہ انکوڈنگ کے عمل کو بالکل الٹ دیتا ہے۔</p>\n<p>آپ اسٹرنگ کو ٹول میں پیسٹ کرتے ہیں، اور ڈی کوڈ شدہ تصویر اپنے ابعاد اور فائل سائز کے ساتھ پیش نظارہ کے طور پر ظاہر ہوتی ہے۔ پھر آپ اسے اصل فارمیٹ یا کسی اور فارمیٹ میں ڈاؤن لوڈ کرتے ہیں۔</p>\n<p>ٹول data:image پریفکس والی اور بغیر پریفکس والی دونوں اسٹرنگ قبول کرتا ہے۔ یہ URL-safe قسم اور حادثاتی لائن بریک والی اسٹرنگ بھی سنبھالتا ہے، جو کاپی کرتے وقت عام ہوتی ہیں۔</p>\n<p>سب کچھ آپ کے براؤزر میں مقامی طور پر چلتا ہے۔ اسٹرنگ آپ کے ڈیوائس پر ڈی کوڈ ہوتی ہے، اور نہ متن اور نہ تصویر کسی سرور پر اپ لوڈ ہوتی ہے۔</p>\n<h2 id=\"how-decoding-works\">Base64 ڈی کوڈنگ کیسے کام کرتی ہے</h2>\n<p>ڈی کوڈنگ اسٹرنگ کو ایک وقت میں چار حروف پڑھتی ہے۔ چار حروف کا ہر گروپ 24 بٹ ڈیٹا لے جاتا ہے، جسے ڈی کوڈر واپس تین بائٹ اصل ڈیٹا میں تقسیم کر دیتا ہے۔</p>\n<p>اسٹرنگ کے آخر میں برابر کے نشان پیڈنگ ہوتے ہیں، اور وہ ڈی کوڈر کو بتاتے ہیں کہ آخری گروپ میں کتنے بائٹ ہیں۔ ایک برابر کا نشان دو بائٹ اور دو برابر کے نشان ایک بائٹ بتاتے ہیں۔</p>\n<p>یہ عمل بالکل درست ہوتا ہے۔ درست انکوڈ شدہ اسٹرنگ بائٹ بہ بائٹ وہی فائل ڈی کوڈ کرتی ہے جو انکوڈ کی گئی تھی، بغیر کوالٹی، اینیمیشن یا شفافیت کے نقصان کے۔</p>\n<p>اگر اسٹرنگ خراب ہو تو ڈی کوڈر ٹوٹی تصویر بنانے کے بجائے واضح ایرر کے ساتھ ناکام ہو جاتا ہے۔ یہ تیزی سے ناکام ہونے والا برتاؤ اہم ہے، کیونکہ خاموشی سے خراب تصویر خطرناک ہوتی ہے۔</p>\n<h2 id=\"with-and-without-prefix\">data:image پریفکس والی اور بغیر والی اسٹرنگ</h2>\n<p>Base64 تصویری اسٹرنگ دو شکلوں میں آتی ہیں۔ مکمل Data URL data:image/png;base64 سے شروع ہوتا ہے، جس کے بعد اسٹرنگ آتی ہے، جبکہ خام اسٹرنگ صرف انکوڈ شدہ حروف ہوتی ہے۔</p>\n<p>ڈی کوڈر دونوں قبول کرتا ہے۔ ویب صفحے سے مکمل Data URL پیسٹ کریں، یا JSON پے لوڈ سے خام اسٹرنگ پیسٹ کریں، اور ٹول خود سمجھ جاتا ہے کہ اسے کون سی شکل ملی ہے۔</p>\n<p>یہ اس لیے اہمیت رکھتا ہے کیونکہ دونوں شکلیں مختلف جگہوں پر ظاہر ہوتی ہیں۔ ویب کوڈ Data URL استعمال کرتا ہے، جبکہ API اور ڈیٹا بیس عام طور پر خام اسٹرنگ کو میڈیا قسم کے ساتھ محفوظ کرتے ہیں۔</p>\n<p>جب آپ اسٹرنگ پیسٹ کریں تو چیک کریں کہ کیا یہ data: سے شروع ہوتی ہے۔ اگر ہاں تو میڈیا قسم پہلے سے اعلان شدہ ہے۔ اگر نہیں تو ڈی کوڈر تصویر کے ہیڈر سے فارمیٹ پڑھتا ہے۔</p>\n<h2 id=\"url-safe-and-line-breaks\">URL-Safe قسم اور لائن بریک</h2>\n<p>معیاری Base64 پلس اور سلیش حروف استعمال کرتا ہے، جن کے URL کے اندر خاص معنی ہوتے ہیں۔ URL-safe قسم انہیں ڈیش اور انڈر اسکور سے بدل دیتی ہے تاکہ وہ لنک میں محفوظ رہیں۔</p>\n<p>ڈی کوڈر دونوں حروف تہجی سمجھتا ہے۔ URL پیرامیٹر سے کاپی شدہ اسٹرنگ JSON فائل سے کاپی شدہ اسٹرنگ جیسی ہی اچھی طرح ڈی کوڈ ہوتی ہے، بغیر دستی تبدیلی کے۔</p>\n<p>لائن بریک دوسرا عام حادثہ ہیں۔ ای میل کلائنٹ اور دستاویزات لمبی اسٹرنگ کو لائنوں پر لپیٹ دیتے ہیں، اور ایسے بریک شامل کر دیتے ہیں جو انکوڈنگ کا حصہ نہیں ہوتے۔</p>\n<p>ڈی کوڈر ان بریک کو برداشت کرتا ہے اور نظر انداز کر دیتا ہے۔ یہ اضافی جگہیں بھی برداشت کرتا ہے، اس لیے لپیٹی ہوئی، اقتباس والی یا ارد گرد خالی جگہ والی اسٹرنگ بھی کام کرتی ہے۔</p>\n<h2 id=\"auto-decode-on-paste\">پیسٹ پر خودکار ڈی کوڈ</h2>\n<p>ڈی کوڈ کرنے کے لیے آپ کو بٹن دبانے کی ضرورت نہیں۔ ٹول میں Base64 اسٹرنگ پیسٹ کرتے ہی ڈی کوڈ خود بخود شروع ہو جاتا ہے، اور پیش نظارہ لمحوں میں ظاہر ہوتا ہے۔</p>\n<p>خودکار ڈی کوڈنگ چھوٹی سہولت ہے جو بہت سی اسٹرنگ پر کام کرتے وقت اہمیت رکھتی ہے۔ پیسٹ کریں، پیش نظارہ چیک کریں، ڈاؤن لوڈ کریں، اور اگلی پیسٹ کریں، بغیر کسی اضافی کلک کے۔</p>\n<p>اگر اسٹرنگ بہت لمبی ہو تو ڈی کوڈ میں ایک یا دو سیکنڈ لگ سکتے ہیں۔ کئی میگا بائٹ والی اسٹرنگ میں بہت سا متن ہوتا ہے، اور براؤزر کو اسے واپس بائٹ میں بدلنے میں لمحہ لگتا ہے۔</p>\n<p>ٹول براؤزر کی اجازت والی رفتار سے ڈی کوڈ کرتا ہے، اور اسے سست کرنے کے لیے کوئی سرور راؤنڈ ٹرپ نہیں ہوتا۔ بڑی اسٹرنگ آپ کے اپنے ڈیوائس کی رفتار سے ڈی کوڈ ہوتی ہے۔</p>\n<h2 id=\"checkerboard-preview\">چیکر بورڈ پیش نظارہ</h2>\n<p>ڈی کوڈ شدہ تصویر چیکر بورڈ پس منظر پر ظاہر ہوتی ہے، جو شفافیت دکھانے کا معیاری طریقہ ہے۔ تصویر کے پیچھے سرمئی اور سفید مربع ان جگہوں کو نشان زد کرتے ہیں جہاں تصویر شفاف ہے۔</p>\n<p>چیکر بورڈ آئیکن اور لوگو کے لیے خاص طور پر مفید ہے۔ شفاف پس منظر والا PNG سادہ سفید پس منظر پر سفید پس منظر والے PNG جیسا ہی لگتا ہے، مگر چیکر بورڈ پر فرق صاف نظر آتا ہے۔</p>\n<p>اگر چیکر بورڈ اس جگہ کے بیچ سے نظر آئے جہاں ٹھوس تصویر ہونی چاہیے تو ماخذ تصویر میں وہاں واقعی شفافیت ہے۔ یہ فائل کے بارے میں معلومات ہے، غلطی نہیں۔</p>\n<p>پیش نظارہ کو ڈاؤن لوڈ فارمیٹ طے کرنے کے لیے استعمال کریں۔ اگر تصویر میں شفافیت ہے جسے رکھنا ہو تو اسے PNG یا اصل فارمیٹ میں ڈاؤن لوڈ کریں، JPG میں نہیں۔</p>\n<h2 id=\"metrics-shown\">میٹرکس: ابعاد، فارمیٹ اور سائز</h2>\n<p>پیش نظارہ کے ساتھ ٹول ڈی کوڈ شدہ تصویر کے ابعاد پکسل میں، اس کا پہچانا گیا فارمیٹ، اور بائنری فائل سائز کلو بائٹ یا میگا بائٹ میں دکھاتا ہے۔</p>\n<p>بائنری سائز ہمیشہ آپ کی پیسٹ شدہ Base64 متن سے تقریباً ایک چوتھائی چھوٹا ہوتا ہے۔ یہ 33 فیصد انکوڈنگ اوور ہیڈ الٹا چل رہا ہے، اور فرق بالکل متوقع ہے۔</p>\n<p>ابعاد بتاتے ہیں کہ تصویر آپ کے مقصد کے لیے قابلِ استعمال ہے یا نہیں۔ اسٹرنگ سے ڈی کوڈ شدہ 64 بائی 64 آئیکن فیویکن ہے، ہیرو تصویر نہیں، اور کوئی ڈاؤن لوڈ فارمیٹ اسے بڑا نہیں کر سکتا۔</p>\n<p>فارمیٹ بھی چیک کریں۔ جو اسٹرنگ PNG ہونے کا دعویٰ کرے مگر JPEG ڈی کوڈ ہو وہ ماخذ کے بارے میں کچھ بتاتی ہے، اور ڈاؤن لوڈ آپشن اس کے مطابق بدلتے ہیں۔</p>\n<h2 id=\"download-formats\">ڈاؤن لوڈ فارمیٹ: اصل، PNG، JPG، WebP</h2>\n<p>اسٹرنگ ڈی کوڈ ہونے کے بعد آپ ڈاؤن لوڈ فارمیٹ چنتے ہیں۔ اصل فائل کو بالکل ویسا ہی رکھتا ہے جیسا انکوڈ کیا گیا تھا، بائٹ بہ بائٹ، جو سب سے محفوظ انتخاب ہے جب آپ کو یقین نہ ہو۔</p>\n<p>PNG شفافیت یا تیز کناروں والی تصاویر کے لیے درست انتخاب ہے۔ یہ پکسل کو بالکل محفوظ رکھتا ہے اور الفا چینل برقرار رکھتا ہے، اس لیے لوگو اور آئیکن بچ جاتے ہیں۔</p>\n<p>JPG ان تصاویر کے لیے درست انتخاب ہے جنہیں چھوٹا ہونا چاہیے۔ یہ تصویر کو کمپریس کرتا ہے اور شفافیت چھوڑ دیتا ہے، اس لیے اسے صرف تب استعمال کریں جب تصویر مکمل غیر شفاف ہو۔</p>\n<p>WebP جدید درمیانی راستہ ہے: زیادہ تر تصاویر کے لیے PNG سے چھوٹا، اور شفافیت سپورٹ بھی شامل۔ جب منزل جدید ویب ہو تو یہ اچھا ڈیفالٹ ہے۔</p>\n<h2 id=\"transparency-and-jpg\">شفافیت اور JPG کا جال</h2>\n<p>شفافیت وہ آسان ترین چیز ہے جو ڈی کوڈ کرتے وقت کھو جاتی ہے۔ شفاف پس منظر والا PNG جب JPG کے طور پر ڈاؤن لوڈ ہو تو اس کی شفاف جگہیں بھر جاتی ہیں، عام طور پر سفید سے۔</p>\n<p>یہ بھرنا مستقل ہوتا ہے۔ ایک بار تصویر JPG کے طور پر محفوظ ہو جائے تو شفافیت کی معلومات ختم ہو جاتی ہے، اور اسے واپس PNG میں بدلنے سے بحال نہیں ہوتی۔</p>\n<p>JPG چننے سے پہلے ہمیشہ چیکر بورڈ پیش نظارہ چیک کریں۔ اگر تصویر کا کوئی حصہ چیکر بورڈ دکھائے تو اس میں شفافیت ہے، اور JPG غلط فارمیٹ ہے۔</p>\n<p>شک ہو تو اصل کے طور پر ڈاؤن لوڈ کریں۔ اس سے فائل بالکل ویسے ہی محفوظ رہتی ہے جیسا انکوڈ کیا گیا تھا، اور آپ اسے درست معائنہ کرنے کے بعد بدل سکتے ہیں۔</p>\n<h2 id=\"animated-gif-and-svg\">اینیمیٹڈ GIF اور ویکٹر SVG</h2>\n<p>اینیمیٹڈ GIF اصل کے طور پر ڈاؤن لوڈ ہونے پر برقرار رہتے ہیں۔ فریم، وقت اور لوپ سیٹنگ سب بائنری ڈیٹا کا حصہ ہیں، اور ڈی کوڈنگ انہیں چھوتی نہیں۔</p>\n<p>اینیمیٹڈ GIF کو PNG یا JPG میں بدلنا اینیمیشن کو تباہ کر دیتا ہے، کیونکہ وہ فارمیٹ ایک مستقل فریم رکھتے ہیں۔ ٹول صرف پہلا فریم دکھا کر آپ کو خبردار کرے گا۔</p>\n<p>SVG فائلیں ویکٹر ہیں، اور وہ واپس وہی SVG کوڈ ڈی کوڈ کرتی ہیں جو انکوڈ کیا گیا تھا۔ اصل کے طور پر ڈاؤن لوڈ ہونے پر فائل درست SVG ہوتی ہے جو بغیر کوالٹی کھوئے اسکیل ہوتی ہے۔</p>\n<p>آپ ڈی کوڈ شدہ SVG کو راسٹر PNG میں بھی بدل سکتے ہیں۔ یہ تب مفید ہوتا ہے جب منزل کو اسکیل ہونے والے ویکٹر کے بجائے فکسڈ سائز تصویر چاہیے ہو، اور ٹول یہ قدم سنبھالتا ہے۔</p>\n<h2 id=\"error-handling\">خراب اسٹرنگ کے ساتھ کیا ہوتا ہے</h2>\n<p>خراب یا غیر تصویری Base64 اسٹرنگ واضح ایرر پیغام کے ساتھ ناکام ہو جاتی ہے۔ ٹول اندازہ نہیں لگاتا، اور نہ جزوی یا ٹوٹی تصویری فائل بناتا ہے۔</p>\n<p>عام وجوہات میں وہ اسٹرنگ شامل ہے جو کاپی کرتے وقت کٹ گئی ہو، وہ حروف جو چیٹ ایپ یا دستاویز ایڈیٹر نے بدل دیے ہوں، یا وہ اسٹرنگ جو کبھی تصویر تھی ہی نہیں۔</p>\n<p>جب آپ ایرر دیکھیں تو پہلے اسٹرنگ چیک کریں۔ اگر ممکن ہو تو اس کی لمبائی اصل سے ملائیں، اور شروع یا آخر میں غائب حروف تلاش کریں، جو سب سے عام جگہ ہے۔</p>\n<p>اگر اسٹرنگ API جواب سے آئی ہو تو چیک کریں کہ کیا جواب مختصر کٹ گیا تھا۔ کٹا ہوا JSON پے لوڈ کٹی ہوئی اسٹرنگ بناتا ہے، اور کوئی ڈی کوڈر اسے مرمت نہیں کر سکتا۔</p>\n<h2 id=\"svg-without-base64-marker\">base64 مارکر کے بغیر SVG</h2>\n<p>کچھ SVG Data URL سرے سے Base64 نہیں ہوتے۔ وہ SVG کوڈ کو سیدھا URL انکوڈ شدہ متن کے طور پر لے جاتے ہیں، اور وہ data:image/svg+xml جیسے لگتے ہیں بغیر semicolon base64 مارکر کے۔</p>\n<p>ایسی اسٹرنگ کو ڈی کوڈر میں پیسٹ کرنے سے انکوڈنگ ایرر آتا ہے، کیونکہ ٹول Base64 حروف کی توقع رکھتا ہے اور اسے زاویہ بریکٹ اور اقتباس ملتے ہیں۔</p>\n<p>حل یہ ہے کہ شکل کو پہچانیں۔ اگر اسٹرنگ میں پڑھنے کے قابل SVG ٹیگ جیسے svg اور path ہوں تو یہ سادہ SVG Data URL ہے، Base64 والا نہیں، اور اسے ڈی کوڈنگ کی ضرورت نہیں۔</p>\n<p>اس متن کو سیدھا .svg فائل کے طور پر محفوظ کریں۔ ٹیکسٹ ایڈیٹر کھولیں، ڈی کوڈ شدہ SVG کوڈ پیسٹ کریں، اور اسے svg ایکسٹینشن کے ساتھ محفوظ کریں تاکہ درست ویکٹر فائل بنے۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: ڈی کوڈنگ آپ کے براؤزر میں ہوتی ہے</h2>\n<p>Base64 اسٹرنگ میں اکثر حساس مواد ہوتا ہے: اندرونی API جواب، نجی آئیکن، QR ٹوکن، یا خفیہ ڈایاگرام۔ ایسی اسٹرنگ کو آن لائن ٹول میں پیسٹ کرنا خطرناک ہو سکتا ہے۔</p>\n<p>یہ ڈی کوڈر مقامی طور پر کام کرتا ہے۔ اسٹرنگ آپ کے براؤزر میں پیسٹ ہوتی ہے، آپ کے ڈیوائس پر ڈی کوڈ ہوتی ہے، اور نتیجہ تصویر آپ کے کمپیوٹر سے کبھی باہر نہیں جاتی۔</p>\n<p>اس کا مطلب یہ بھی ہے کہ صفحہ لوڈ ہونے کے بعد ٹول آف لائن کام کرتا ہے۔ آپ ہوائی جہاز میں، محفوظ دفتر میں، یا بغیر کنکشن کے کہیں بھی اسٹرنگ ڈی کوڈ کر سکتے ہیں۔</p>\n<p>اندرونی ڈیٹا سنبھالنے والی ٹیموں کے لیے مقامی ڈی کوڈنگ وہ خصوصیت ہے جو ٹول کو بالکل استعمال کے قابل محفوظ بناتی ہے۔ اسٹرنگ یا تصویر کی کوئی کاپی کہیں اور موجود نہیں ہوتی۔</p>\n<h2 id=\"decoding-from-documents-and-qr\">دستاویزات میں ملنے والی تصاویر ڈی کوڈ کرنا</h2>\n<p>Base64 اسٹرنگ ایسی جگہوں پر چھپی ہوتی ہیں جہاں آپ توقع نہ کریں۔ Word دستاویزات، PDF اور ڈیزائن فائلیں کبھی کبھی ایمبیڈ شدہ تصاویر کو اپنے XML یا JSON ڈھانچے کے اندر Base64 کے طور پر محفوظ کرتی ہیں۔</p>\n<p>جب آپ کو ایسا ٹکڑا ملے تو اسٹرنگ کو احتیاط سے کاپی کریں، اس کی پوری لمبائی سمیت۔ دستاویز فارمیٹ اکثر لمبی اسٹرنگ کو لائنوں پر تقسیم کر دیتے ہیں، اس لیے چیک کریں کہ کوئی حصہ رہ نہ گیا ہو۔</p>\n<p>QR کوڈ مختلف صورت ہے۔ QR کوڈ میں Data URL کے طور پر چھوٹی تصویر ہو سکتی ہے، مگر زیادہ تر QR کوڈ میں لنک ہوتا ہے۔ اگر کوڈ text سے شروع ہونے والے متن میں ڈی کوڈ ہو تو وہ تصویر نہیں بلکہ لنک ہے۔</p>\n<p>چیٹ ایپلیکیشن دوسرا عام ماخذ ہیں۔ کچھ چیٹ سسٹم تصاویر کو اپنے میسج پے لوڈ کے اندر Base64 کے طور پر بھیجتے ہیں، اور کاپی شدہ پے لوڈ کو ڈی کوڈ کر کے تصویر واپس لائی جا سکتی ہے۔</p>\n<p>ہر صورت میں وہی جانچ لاگو ہوتی ہے: تصدیق کریں کہ اسٹرنگ مکمل ہے، سروں پر کٹنے پر نظر رکھیں، اور پہلے اصل کے طور پر ڈاؤن لوڈ کریں۔ اصل فارمیٹ سب سے محفوظ نقطہ آغاز ہے۔</p>\n<p>غیر معتبر دستاویزات سے آنے والی اسٹرنگ کے ساتھ محتاط رہیں۔ ڈی کوڈنگ خود محفوظ ہے، مگر ارد گرد کی دستاویز فشنگ کی کوشش ہو سکتی ہے، اس لیے تصویر کے مواد پر اندھا بھروسا نہ کریں۔</p>\n<h2 id=\"how-to-use-the-tool\">Base64 to Image ڈی کوڈر کیسے استعمال کریں</h2>\n<p><a href=\"/ur/base64-ko-tasveer-mein-convert-karein/\">Base64 to image decoder</a> کھولیں اور اپنی اسٹرنگ ان پٹ جگہ میں پیسٹ کریں۔ ڈی کوڈنگ خود بخود شروع ہو جاتی ہے، اور پیش نظارہ اپنے ابعاد اور فائل سائز کے ساتھ ظاہر ہوتا ہے۔</p>\n<p>شفافیت کے لیے چیکر بورڈ پیش نظارہ چیک کریں، پھر ڈاؤن لوڈ فارمیٹ چنیں: فائل بالکل رکھنے کے لیے اصل، یا بدلنے کے لیے PNG، JPG یا WebP۔ فائل فوراً ڈاؤن لوڈ ہو جاتی ہے۔</p>\n<p>اگر اسٹرنگ ناکام ہو تو ایرر پیغام پڑھیں اور کٹنے یا غائب پریفکس کی جانچ کریں۔ زیادہ تر ناکامیاں خراب اسٹرنگ ہوتی ہیں، ٹول کا مسئلہ نہیں۔</p>\n<p>مرحلہ بہ مرحلہ ورژن کے لیے <a href=\"/ur/blog/base64-ko-tasveer-mein-kaise-convert-karein/\">How to Convert Base64 to an Image</a> پڑھیں، اور کارکردگی کے موازنے کے لیے <a href=\"/ur/blog/base64-vs-tasveer-files/\">Base64 vs Image Files: Performance and Use Cases</a> دیکھیں۔</p>\n";

